-- Wallet Service schema (wallet_db). Contract: docs/spec.md §2 (Wallet, LedgerEntry,
-- TransferSettlement, ProcessedMessage, OutboxMessage), §1.5 and §4.7.
-- Money is NUMERIC(19,2); timestamps are TIMESTAMPTZ; UUIDs are generated by the application.

-- ---------------------------------------------------------------- wallets
CREATE TABLE wallets (
    wallet_id  UUID          NOT NULL,
    user_id    UUID          NOT NULL,
    balance    NUMERIC(19,2) NOT NULL,
    currency   VARCHAR(3)    NOT NULL,
    version    BIGINT        NOT NULL DEFAULT 0,
    updated_at TIMESTAMPTZ   NOT NULL,
    CONSTRAINT pk_wallets PRIMARY KEY (wallet_id),
    CONSTRAINT uq_wallets_user_id UNIQUE (user_id),
    CONSTRAINT ck_wallets_balance_non_negative CHECK (balance >= 0),
    CONSTRAINT ck_wallets_currency_cop CHECK (currency = 'COP'),
    CONSTRAINT ck_wallets_version_non_negative CHECK (version >= 0)
);

-- ---------------------------------------------------------------- ledger_entries (append-only)
CREATE TABLE ledger_entries (
    entry_id      UUID          NOT NULL,
    wallet_id     UUID          NOT NULL,
    transfer_id   UUID,
    type          VARCHAR(16)   NOT NULL,
    amount        NUMERIC(19,2) NOT NULL,
    balance_after NUMERIC(19,2) NOT NULL,
    created_at    TIMESTAMPTZ   NOT NULL,
    CONSTRAINT pk_ledger_entries PRIMARY KEY (entry_id),
    CONSTRAINT fk_ledger_wallet FOREIGN KEY (wallet_id) REFERENCES wallets (wallet_id),
    CONSTRAINT uq_ledger_transfer_type UNIQUE (transfer_id, type),
    CONSTRAINT ck_ledger_type CHECK (type IN ('OPENING', 'DEBIT', 'CREDIT', 'REVERSAL')),
    CONSTRAINT ck_ledger_amount_positive CHECK (amount > 0),
    CONSTRAINT ck_ledger_balance_after_non_negative CHECK (balance_after >= 0),
    CONSTRAINT ck_ledger_transfer_id_null_only_for_opening CHECK ((type = 'OPENING') = (transfer_id IS NULL))
);

-- NULLs never collide in a UNIQUE constraint, so uq_ledger_transfer_type cannot enforce this.
CREATE UNIQUE INDEX uq_ledger_one_opening_per_wallet ON ledger_entries (wallet_id) WHERE type = 'OPENING';

CREATE INDEX ix_ledger_wallet ON ledger_entries (wallet_id);

CREATE FUNCTION reject_ledger_change() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    RAISE EXCEPTION 'ledger_entries is append-only: % is not allowed', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER trg_ledger_reject_update_delete
    BEFORE UPDATE OR DELETE ON ledger_entries
    FOR EACH ROW EXECUTE FUNCTION reject_ledger_change();

CREATE TRIGGER trg_ledger_reject_truncate
    BEFORE TRUNCATE ON ledger_entries
    FOR EACH STATEMENT EXECUTE FUNCTION reject_ledger_change();

-- ---------------------------------------------------------------- transfer_settlements
CREATE TABLE transfer_settlements (
    transfer_id UUID        NOT NULL,
    outcome     VARCHAR(16) NOT NULL,
    settled_at  TIMESTAMPTZ NOT NULL,
    CONSTRAINT pk_transfer_settlements PRIMARY KEY (transfer_id),
    CONSTRAINT ck_settlements_outcome CHECK (outcome IN ('CREDITED', 'REVERSED'))
);

-- ---------------------------------------------------------------- processed_messages
CREATE TABLE processed_messages (
    message_id     UUID         NOT NULL,
    consumer       VARCHAR(64)  NOT NULL,
    processed_at   TIMESTAMPTZ  NOT NULL,
    result_type    VARCHAR(32),
    result_payload JSONB,
    CONSTRAINT pk_processed_messages PRIMARY KEY (message_id, consumer),
    CONSTRAINT ck_processed_result_type CHECK (result_type IN
        ('WalletDebited', 'DebitRejected', 'WalletCredited', 'CreditFailed', 'DebitReversed'))
);

-- ---------------------------------------------------------------- outbox_messages
CREATE TABLE outbox_messages (
    id           UUID         NOT NULL,
    exchange     VARCHAR(128) NOT NULL,
    routing_key  VARCHAR(128) NOT NULL,
    payload      JSONB        NOT NULL,
    created_at   TIMESTAMPTZ  NOT NULL,
    published_at TIMESTAMPTZ,
    CONSTRAINT pk_outbox_messages PRIMARY KEY (id)
);

-- Lets the relay find pending rows without scanning published ones.
CREATE INDEX ix_outbox_pending ON outbox_messages (created_at) WHERE published_at IS NULL;
